// SOAL 2: MENGAKSES ELEMEN ARRAY

const bahasaPemrograman = [
    "JavaScript",
    "PHP",
    "Python",
    "Java",
    "C#"
];

// 1. Bahasa pemrograman pertama
console.log("Bahasa pertama:", bahasaPemrograman[0]);

// 2. Bahasa pemrograman ketiga
console.log("Bahasa ketiga:", bahasaPemrograman[2]);

// 3. Bahasa pemrograman terakhir
console.log("Bahasa terakhir:", bahasaPemrograman[4]);

// 4. Mengakses elemen indeks 7
console.log("Indeks 7:", bahasaPemrograman[7]);

// Penjelasan
console.log("Indeks 7 menghasilkan undefined karena Array hanya memiliki indeks 0 sampai 4.");